#pragma once
#include <Arduino.h>
#include "config.hpp"

// Event types generated by the HW-040 rotary encoder
enum EncoderEventType {
    ENCODER_EVENT_NONE = 0,
    ENCODER_EVENT_ROT_CW,    // Rotated clockwise (navigate down / next)
    ENCODER_EVENT_ROT_CCW,   // Rotated counter-clockwise (navigate up / prev)
    ENCODER_EVENT_CLICK      // Push button pressed and released
};

// Global task handle for the encoder scanning task
extern TaskHandle_t encoderTaskHandle;

// Initialize HW-040 GPIO pins and FreeRTOS event queue
bool initEncoder();

// Poll for an available encoder event (non-blocking by default)
bool getEncoderEvent(EncoderEventType& outEvent, TickType_t waitTicks = 0);

// FreeRTOS background task scanning encoder state with debouncing
void encoderTask(void *pvParameters);

